theory.code:
a, k = [1, 2, 4, 7], 6
l, r = 0, len(a) - 1
ok = False
while l < r:
    s = a[l] + a[r]
    if s == k:
        ok = True
        break
    if s < k:
        l += 1
    else:
        r -= 1
print("YES" if ok else "NO")

